// Copyright 2026 Anthropic PBC
// SPDX-License-Identifier: Apache-2.0
//
// What counts as risky: reads a shell command line and returns its first risky
// segment, following `cd`, `pushd`, `popd` and `git -C` to where it would run.

export type GitKind = 'git-reset' | 'git-clean' | 'git-push-force' | 'git-checkout'

export type GitRisk = { kind: GitKind; label: string; args: string[]; dir: string | null }

export type Risk =
  | { kind: 'rm'; label: string; targets: string[]; dir: string | null }
  | GitRisk
  | { kind: 'migrate'; tool: string; label: string; dir: string | null }

// A segment that only moves the folder: where to, null for the session folder.
type Move = { cd: string | null }

type Step = Risk | Move | null

// sudo options that take a value, so the value isn't read as the command.
const SUDO_VALUE_OPTIONS = new Set(['-u', '-g', '-C', '-D', '-h', '-p', '-r', '-t', '-T', '-U'])
// Commands that only read, so a bare word "migrate" in them isn't a migration.
const READ_ONLY = new Set(['ls', 'cat', 'echo', 'printf', 'grep', 'rg', 'find', 'less', 'head', 'tail', 'cd', 'git'])
// Words that can come before the real command without changing what it does.
const PREFIXES = new Set(['command', 'exec', 'env', 'nohup', 'time', 'then', 'do', 'else', '!'])
const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/

const isMove = (step: Step): step is Move => step !== null && 'cd' in step

/** A folder a later `cd arg` moves to, given the folder so far (null = the session folder). */
export function joinDir(dir: string | null, arg: string | undefined): string {
  if (arg === undefined || arg === '~' || arg.startsWith('/') || arg.startsWith('~/')) {
    return arg ?? '~'
  }

  return dir ? `${dir}/${arg}` : arg
}

/** Splits one segment into words, honouring quotes. Good enough to read flags and paths. */
export function tokenize(text: string): string[] {
  const words: string[] = []
  for (const match of text.matchAll(/"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+)/g)) {
    words.push(match[1] ?? match[2] ?? match[3] ?? '')
  }

  return words
}

/** `NAME=value` segments (or `export NAME=value`) set earlier on the line, so `rm -rf $NAME` can be measured. */
function readAssignments(segment: string, vars: Map<string, string>): void {
  const words = tokenize(segment.trim())
  if (words[0] === 'export') words.shift()
  if (words.length === 0 || !words.every(word => ASSIGNMENT.test(word))) return
  for (const word of words) {
    const at = word.indexOf('=')
    vars.set(word.slice(0, at), expandVars(word.slice(at + 1), vars))
  }
}

/** `$NAME` and `${NAME}` from earlier assignments on the line; anything else stays as written. */
export function expandVars(text: string, vars: Map<string, string>): string {
  return text.replace(/\$(?:\{([A-Za-z_][A-Za-z0-9_]*)\}|([A-Za-z_][A-Za-z0-9_]*))/g, (whole, braced, bare) => vars.get(braced ?? bare) ?? whole)
}

/** The first risky segment of a shell command, or null. */
export function classify(command: string): Risk | null {
  let dir: string | null = null
  const scopes: (string | null)[] = [] // dir to restore when a ( subshell ) closes
  const pushed: (string | null)[] = [] // pushd stack, for popd
  const vars = new Map<string, string>()
  for (const raw of command.split(/&&|\|\||;|\||\n/)) {
    readAssignments(raw, vars)
    const opens = raw.match(/^\s*\(+/)?.[0].trim().length ?? 0
    // Trailing redirects and & don't hide a closing ) : `(cd sub && make) > log`.
    const tail = raw.replace(/(?:\s*(?:\d*>>?|&>>?|<)\s*\S+|\s*&)+\s*$/, '')
    const closes = tail.match(/\)+\s*$/)?.[0].trim().length ?? 0
    for (let k = 0; k < opens; k += 1) scopes.push(dir)
    const step = classifySegment(expandVars(raw, vars), dir, pushed)
    if (step !== null && !isMove(step)) return step
    if (isMove(step)) dir = step.cd // a cd, pushd or popd moved the folder
    for (let k = 0; k < closes && scopes.length > 0; k += 1) dir = scopes.pop() ?? null // a cd inside ( ... ) doesn't outlive it
  }

  return null
}

/** The words of a segment with sudo, VAR=value, nice and harmless prefixes taken off. */
function commandWords(segment: string): string[] {
  const words = tokenize(segment.trim().replace(/^[({]+\s*/, '').replace(/\s*[)}]+$/, ''))
  while (words.length > 0 && ASSIGNMENT.test(words[0] ?? '')) words.shift()
  if (words[0] === 'sudo') {
    words.shift()
    while (words.length > 0 && (words[0] ?? '').startsWith('-')) {
      const option = words.shift() ?? ''
      if (SUDO_VALUE_OPTIONS.has(option)) words.shift()
    }
  }
  while (words.length > 0 && (PREFIXES.has(words[0] ?? '') || ASSIGNMENT.test(words[0] ?? ''))) words.shift()
  if (words[0] === 'nice') {
    words.shift()
    const option: string = words[0] ?? ''
    if (option === '-n') words.splice(0, 2)
    else if (/^-\d+$/.test(option)) words.shift()
  }

  return words
}

/** One segment: a risk, a folder change, or null. */
function classifySegment(segment: string, dir: string | null, pushed: (string | null)[]): Step {
  const words = commandWords(segment)
  const [first, ...args] = words
  if (first === undefined) return null
  const cmd = first.replace(/^\\/, '') // \rm skips aliases; it's still rm
  if (cmd === 'cd') return { cd: args[0] === '-' ? '-' : joinDir(dir, args[0]) }
  if (cmd === 'pushd') {
    pushed.push(dir)

    return { cd: joinDir(dir, args[0]) }
  }
  if (cmd === 'popd') return { cd: pushed.length > 0 ? (pushed.pop() ?? null) : '-' }
  if (cmd === 'rm' || cmd.endsWith('/rm')) {
    const risk = classifyRm(args, dir)
    if (risk !== null) return risk
  }
  if (cmd === 'git') {
    const risk = classifyGit(args, dir)
    if (risk !== null) return risk
  }

  return classifyMigrate(words, cmd, dir)
}

function classifyRm(args: string[], dir: string | null): Risk | null {
  const flags = args.filter(a => a.startsWith('-'))
  const recursive = flags.some(f => f === '--recursive' || (/^-[^-]/.test(f) && /[rR]/.test(f)))
  const force = flags.some(f => f === '--force' || (/^-[^-]/.test(f) && f.includes('f')))
  if (!recursive && !force) return null
  const targets = args.filter(a => !a.startsWith('-') || a === '-')

  return { kind: 'rm', label: `rm ${flags.join(' ')}`.trim(), targets, dir }
}

/** Git's own options come before the subcommand; -C moves where it runs. */
function gitSubcommand(args: string[], dir: string | null): { at: number; dir: string | null } {
  let gitDir = dir
  let at = 0
  while (at < args.length && (args[at] ?? '').startsWith('-')) {
    if (args[at] === '-C' && at + 1 < args.length) {
      gitDir = joinDir(gitDir, args[at + 1])
      at += 2
    } else if (args[at] === '-c' && at + 1 < args.length) {
      at += 2
    } else {
      at += 1
    }
  }

  return { at, dir: gitDir }
}

function classifyGit(args: string[], dir: string | null): Risk | null {
  const found = gitSubcommand(args, dir)
  const sub = args[found.at]
  const rest = args.slice(found.at + 1)
  const at = found.dir
  if (sub === 'reset' && rest.includes('--hard')) return { kind: 'git-reset', label: 'git reset --hard', args: rest, dir: at }
  if (sub === 'clean') return { kind: 'git-clean', label: 'git clean', args: rest, dir: at }
  const isForce = rest.some(a => a === '--force' || a === '-f' || a.startsWith('--force-with-lease') || /^\+/.test(a))
  if (sub === 'push' && isForce) return { kind: 'git-push-force', label: 'git push --force', args: rest, dir: at }
  const isStagedOnly = sub === 'restore' && rest.includes('--staged') && !rest.includes('--worktree') && !rest.includes('-W')
  if ((sub === 'checkout' || sub === 'restore') && rest.includes('.') && !isStagedOnly) {
    return { kind: 'git-checkout', label: `git ${sub} -- .`, args: rest, dir: at }
  }

  return null
}

function classifyMigrate(words: string[], cmd: string, dir: string | null): Risk | null {
  const joined = words.join(' ')
  if (/\balembic\s+upgrade\b/.test(joined)) return { kind: 'migrate', tool: 'alembic', label: 'alembic upgrade', dir }
  if (/\bdb:migrate(?!:status\b)/.test(joined)) return { kind: 'migrate', tool: 'rails', label: 'db:migrate', dir }
  if (/\bprisma\s+migrate\b/.test(joined)) return { kind: 'migrate', tool: 'prisma', label: 'prisma migrate', dir }
  if (/\bmanage\.py\s+migrate\b/.test(joined)) return { kind: 'migrate', tool: 'django', label: 'manage.py migrate', dir }
  if (!READ_ONLY.has(cmd) && words.slice(1).includes('migrate')) return { kind: 'migrate', tool: 'unknown', label: 'migrate', dir }

  return null
}

files.hooks/collide.ts:
// The collision guard: an edit to a file another chat on this machine changed within the last
// half hour is held on an Amber card, "Skip this edit" in focus. Every edit that lands is logged
// under this session's own store key (edits.ts) for the others to see. With nobody there to
// answer (a -p run, the SDK) the edit goes ahead: a caution never stalls a headless run.

import type { EngineInterface, Register } from 'claude-code'

import { clashView, minutesSince } from './caution'
import type { LineCount } from './caution'
import { editsKey, findClash, recordEdit } from './edits'
import type { Edit, EditStore } from './edits'
import { PANE_ID, SLEEP_TIMEOUT_MS, hold, take } from './hold'
import type { Decision, Held, HoldIo } from './hold'
import { parseNumstat } from './measure-git'
import { words } from './words'

type On = Parameters<Register>[0]

// MultiEdit is matched by name for builds that still have it.
const EDIT_TOOLS = /^(Write|Edit|MultiEdit|NotebookEdit)$/
const DIFF_TIMEOUT_MS = 5000

const WHY: Record<Exclude<Decision, 'proceed' | 'cancel' | 'error'>, string> = {
  closed: 'the user closed the Blast Radius pane',
  timeout: 'no answer within 10 minutes',
  interrupted: 'the turn was interrupted',
}

// The hold loop's calls, spelled here: the engine follows `$` only within one file.
const holdIo = ($: EngineInterface): HoldIo => ({
  sleep: seconds => $.process.run(['sleep', seconds], { timeoutMs: SLEEP_TIMEOUT_MS }),
  now: () => $.clock.now(),
  open: async rows => (await $.ui.open({ id: PANE_ID, title: 'Blast Radius', focus: true, closeOnEscape: true, rows })).isPlaced,
  close: () => $.ui.close({ id: PANE_ID }),
  redraw: () => $.ui.invalidate('ui.render'),
})

// `$` stays in this file: the store logic gets closures over it.
const storeOf = ($: EngineInterface): EditStore => ({
  get: key => $.store.get(key),
  set: (key, value) => $.store.set(key, value),
  delete: key => $.store.delete(key),
  keys: () => $.store.keys(),
})

function editPath(e: unknown): string {
  const args = e as Record<string, unknown>
  const path = args.file_path ?? args.notebook_path

  return typeof path === 'string' ? path : ''
}

const baseName = (path: string): string => path.split('/').filter(Boolean).pop() ?? path

/** Where the path lands, so two spellings of one file (a symlink, `./`) meet; a new file by its folder's. */
async function realPathOf($: EngineInterface, given: string): Promise<string> {
  const path = given.startsWith('/') ? given : `${await $.session.cwd()}/${given}`
  const own = await $.fs.stat(path, { resolve: true }).catch(() => undefined)
  if (own?.realPath !== undefined) return own.realPath
  const cut = path.lastIndexOf('/')
  const folder = cut < 0 ? '.' : path.slice(0, cut + 1)
  const dir = await $.fs.stat(folder, { resolve: true }).catch(() => undefined)

  return dir?.realPath === undefined ? path : `${dir.realPath.replace(/\/$/, '')}/${path.slice(cut + 1)}`
}

/** Lines the file has uncommitted now, or null outside git or when it has none. */
async function diffOf($: EngineInterface, real: string): Promise<LineCount | null> {
  const folder = real.slice(0, Math.max(1, real.lastIndexOf('/')))
  const ran = await $.process.run(['git', 'diff', '--numstat', '--', real], { cwd: folder, timeoutMs: DIFF_TIMEOUT_MS })
  if (ran.exitCode !== 0) return null
  const [first] = parseNumstat(ran.stdout).values()

  return first ?? null
}

type Clash = { clash: Edit; real: string; signal: AbortSignal }

async function prepare($: EngineInterface, mine: Held, input: Clash): Promise<boolean> {
  const cwd = await $.session.cwd()
  const shown = input.real.startsWith(`${cwd}/`) ? input.real.slice(cwd.length + 1) : input.real
  const card = { clash: input.clash, now: await $.clock.now(), shown, diff: await diffOf($, input.real) }
  mine.view = () => clashView(card)

  return true
}

/** Asks the person; a deny when they skip it, null when the edit goes ahead. */
async function settle($: EngineInterface, input: Clash): Promise<{ deny: string } | null> {
  const minutes = minutesSince(input.clash.at, await $.clock.now())
  if ((await $.session.surfaces()).length === 0) {
    $.ui.log(`blast-radius: another chat edited ${baseName(input.real)} ${minutes} min ago; nobody to ask, so the edit goes ahead`, { to: 'debug' })

    return null
  }
  const mine = await take(holdIo($), { command: input.real, signal: input.signal, canStrike: false })
  const decision = mine === null ? 'interrupted' : await held($, mine, input)
  // A guard that broke lets the edit through: this is a caution, not a lock.
  if (decision === 'proceed' || decision === 'error') return null
  const why = decision === 'cancel' ? words().edit.cancelWhy : WHY[decision]
  if (decision === 'cancel' || decision === 'closed') $.ui.toast(words().edit.skipped)

  return {
    deny: `Blast Radius held this edit and did not make it: ${why}. Another session edited ${input.real} ${minutes} min ago and may still be working on it. Do not retry it unless the user asks you to.`,
  }
}

async function held($: EngineInterface, mine: Held, input: Clash): Promise<Decision> {
  await hold(holdIo($), mine, { signal: input.signal, prepare: () => prepare($, mine, input) })

  return mine.decision ?? 'error'
}

async function projectOf($: EngineInterface): Promise<string> {
  return baseName(await $.session.root())
}

export function editHooks(on: On): void {
  on('tool.call', { tool: EDIT_TOOLS }, async ($, e, next) => {
    const path = editPath(e)
    if (path === '') return next(e)
    const real = await realPathOf($, path)
    const sessionId = await $.session.id()
    const clash = await findClash(storeOf($), { path: real, sessionId, now: await $.clock.now() })
    const refused = clash === null ? null : await settle($, { clash, real, signal: next.signal })
    if (refused !== null) return refused
    const result = await next(e)
    if (result.deny === undefined && result.isError !== true) {
      await recordEdit(storeOf($), { path: real, sessionId, project: await projectOf($), at: await $.clock.now() })
    }

    return result
  }).catch(($, e, next) => next(e))

  // An ended chat is no longer in any file.
  on('session.end', async ($, e, next) => {
    await $.store.delete(editsKey(e.sessionId))

    return next(e)
  }).catch(($, e, next) => next(e))
}

files.hooks/hold.ts:
// Holding one call while the person answers its card: a risky command, an edit another chat
// just made, a command a house rule asks about. One at a time; the card itself is drawn by
// register's ui.render hooks from `current()`.
//
// A hook has 10 s of its own time, but time spent inside a `$` call is free. So the hold loop
// waits on a short `$.process.run(["sleep", ...])` until a button's onPress sets the decision.
// The engine follows `$` only within one file, so each hooks module hands in its own `HoldIo`.

import { motion } from './card'
import type { CardProps } from './card'
import type { View } from './view'

export type Decision = 'proceed' | 'cancel' | 'closed' | 'timeout' | 'interrupted' | 'error'

export type Held = {
  command: string
  // What the card shows, once it is ready to draw; null while it is being measured.
  view: ((isExpanded: boolean) => View) | null
  decision: Decision | null
  where: 'pane' | 'band'
  phase: CardProps['phase']
  isExpanded: boolean
  // Only a delete strikes its rows before it runs.
  canStrike: boolean
}

// The hold loop's calls on `$`, as closures from the hooks module.
export type HoldIo = {
  // `$.process.run(['sleep', seconds], { timeoutMs: SLEEP_TIMEOUT_MS })`
  sleep: (seconds: string) => Promise<unknown>
  now: () => Promise<number>
  // `$.ui.open` of PANE_ID with these rows: whether a surface placed it.
  open: (rows: number) => Promise<boolean>
  close: () => Promise<void>
  redraw: () => void
}

export type HoldOptions = {
  signal: AbortSignal
  // Measures and sets `view`; false when there is nothing to ask, and the call goes ahead.
  prepare: () => Promise<boolean>
}

export const PANE_ID = 'blast-radius'
const POLL_SECONDS = '0.25'
const STRIKE_SECONDS = '0.9'
export const SLEEP_TIMEOUT_MS = 5000
const HOLD_LIMIT_MS = 10 * 60 * 1000
const PANE_ROWS_MAX = 24
const PANE_ROWS_CHROME = 9

// The call being held, or null. One at a time: a second call waits for the first answer.
let held: Held | null = null

export const current = (): Held | null => held

/** Waits for any earlier card to be answered, then claims the hold; null when the turn was interrupted meanwhile. */
export async function take(io: HoldIo, input: { command: string; signal: AbortSignal; canStrike: boolean }): Promise<Held | null> {
  while (held !== null) {
    if (input.signal.aborted) return null
    await io.sleep(POLL_SECONDS)
  }
  // Claimed with no await between the check and the claim, so two waiting calls can't both get through.
  const mine: Held = { command: input.command, view: null, decision: null, where: 'pane', phase: 'asking', isExpanded: false, canStrike: input.canStrike }
  held = mine

  return mine
}

async function waitForDecision(io: HoldIo, mine: Held, signal: AbortSignal): Promise<void> {
  const startedAt = await io.now()
  while (mine.decision === null) {
    if (signal.aborted) {
      mine.decision = 'interrupted'
    } else if ((await io.now()) - startedAt > HOLD_LIMIT_MS) {
      mine.decision = 'timeout'
    } else {
      await io.sleep(POLL_SECONDS)
    }
  }
}

function paneRows(mine: Held): number {
  const rows = mine.view === null ? 0 : mine.view(false).rows.length

  return Math.min(PANE_ROWS_MAX, PANE_ROWS_CHROME + rows)
}

/** Opens the card, waits for the answer and lets the hold go, whatever happens. */
export async function hold(io: HoldIo, mine: Held, options: HoldOptions): Promise<void> {
  let isPlaced = false
  try {
    if (!(await options.prepare())) {
      mine.decision = 'proceed'

      return
    }
    // Every card's pane opens anew, so its drawings cascade in each time (kit/moving.ts).
    motion.reset()
    isPlaced = await io.open(paneRows(mine))
    if (!isPlaced) mine.where = 'band'
    io.redraw()
    await waitForDecision(io, mine, options.signal)
    if (mine.decision === 'proceed' && mine.canStrike) {
      // The rows it is about to delete get struck through, then the pane goes.
      mine.phase = 'striking'
      io.redraw()
      await io.sleep(STRIKE_SECONDS)
    }
  } catch {
    mine.decision = 'error'
  } finally {
    // Close this call's pane before releasing the hold, so the next call's pane can't be the one closed.
    if (isPlaced) await io.close().catch(() => undefined)
    if (held === mine) held = null
    io.redraw()
  }
}

/** Closing the pane (Esc, its close mark) answers as the safe button does. */
export function closeHeld(): void {
  if (held !== null && held.decision === null) held.decision = 'closed'
}

files.hooks/house.ts:
// House rules for the gray zone: a Bash command blast-radius's own rules don't hold and that is
// not plainly read-only is weighed against `.claude/house-rules.md`, when the person wrote one.
// One judge call per command at most (kit/judge.ts, haiku on the person's own account; Jev when
// they opted in), its verdict kept for the session. allow runs it, ask holds it on the Amber
// card, block refuses it. No verdict (no model, a timeout, a stray reply) runs it: a judge that
// failed never stops the person's work.

import type { EngineInterface, Register } from 'claude-code'

import { ruleView } from './caution'
import { classify } from './classify'
import { PANE_ID, SLEEP_TIMEOUT_MS, hold, take } from './hold'
import type { Decision, Held, HoldIo } from './hold'
import { judge } from './kit/judge'
import type { JudgeIo } from './kit/judge'
import { RULES_FILE, instructionsFor, isReadOnly, labelsFor, parseRules, redact, verdictOf } from './rules'
import type { Verdict } from './rules'
import { words } from './words'

type On = Parameters<Register>[0]

const WHY: Record<Exclude<Decision, 'proceed' | 'cancel' | 'error'>, string> = {
  closed: 'the user closed the Blast Radius pane',
  timeout: 'no answer within 10 minutes',
  interrupted: 'the turn was interrupted',
}

// Verdicts for the session, by exact command; dropped when the rules change.
const cache = { rules: '', verdicts: new Map<string, Verdict>() }

// The hold loop's calls, spelled here: the engine follows `$` only within one file.
const holdIo = ($: EngineInterface): HoldIo => ({
  sleep: seconds => $.process.run(['sleep', seconds], { timeoutMs: SLEEP_TIMEOUT_MS }),
  now: () => $.clock.now(),
  open: async rows => (await $.ui.open({ id: PANE_ID, title: 'Blast Radius', focus: true, closeOnEscape: true, rows })).isPlaced,
  close: () => $.ui.close({ id: PANE_ID }),
  redraw: () => $.ui.invalidate('ui.render'),
})

/** The rules in the session's project, or none when it has no rules file. */
async function rulesOf($: EngineInterface): Promise<string[]> {
  const text = await $.fs.read(`${await $.session.root()}/${RULES_FILE}`).catch(() => '')

  return typeof text === 'string' ? parseRules(text) : []
}

async function judged($: EngineInterface, input: { command: string; rules: string[] }): Promise<Verdict | null> {
  const key = input.rules.join('\n')
  if (cache.rules !== key) cache.verdicts.clear()
  cache.rules = key
  const known = cache.verdicts.get(input.command)
  if (known !== undefined) return known
  const env = { backend: await $.env.get('MODZ_JUDGE'), typesafeKey: await $.env.get('TYPESAFE_API_KEY') }
  const io: JudgeIo = { complete: request => $.model.complete(request), fetch: (url, init) => $.http.fetch(url, init), sleep: ms => $.clock.sleep(ms), redact, env }
  const answer = await judge(io, { text: input.command, labels: labelsFor(input.rules), instructions: instructionsFor(input.rules) })
  const verdict = answer === undefined ? null : verdictOf(answer.label, input.rules)
  if (verdict !== null) cache.verdicts.set(input.command, verdict)

  return verdict
}

type Ask = { command: string; rule: string; signal: AbortSignal }

async function prepare($: EngineInterface, mine: Held, input: Ask): Promise<boolean> {
  const card = { command: input.command, rule: input.rule, cwd: await $.session.cwd() }
  mine.view = () => ruleView(card)

  return true
}

/** Holds the command on the card; a deny unless the person runs it. */
async function ask($: EngineInterface, input: Ask): Promise<{ deny: string } | null> {
  const noAnswer = `Blast Radius held this command and did not run it: a house rule (${input.rule}) asks the user first`
  if ((await $.session.surfaces()).length === 0) return { deny: `${noAnswer}, and nobody is here to answer. Do not retry it.` }
  const mine = await take(holdIo($), { command: input.command, signal: input.signal, canStrike: false })
  if (mine !== null) await hold(holdIo($), mine, { signal: input.signal, prepare: () => prepare($, mine, input) })
  const decision = mine?.decision ?? 'interrupted'
  // A card that broke lets the command through: a house rule is a caution, not a lock.
  if (decision === 'proceed' || decision === 'error') return null
  if (decision === 'cancel' || decision === 'closed') $.ui.toast(words().kept)
  const why = decision === 'cancel' ? words().cancelWhy : WHY[decision]

  return { deny: `Blast Radius held this command and did not run it: ${why}. House rule: ${input.rule}. Do not retry it unless the user asks you to.` }
}

/** A new session judges afresh; register's session.start calls it. */
export function resetHouse(): void {
  cache.verdicts.clear()
}

export function houseHooks(on: On): void {
  // Risky commands are blast-radius's own (register.tsx); plain reads are never judged.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const command = String(e.command ?? '')
    if (classify(command) !== null || isReadOnly(command)) return next(e)
    const rules = await rulesOf($)
    if (rules.length === 0) return next(e)
    const verdict = await judged($, { command, rules })
    if (verdict === null) $.ui.log('blast-radius: the house rules got no verdict for a command, so it runs', { to: 'debug' })
    if (verdict === null || verdict.kind === 'allow') return next(e)
    const rule = verdict.rule ?? words().house.anyRule
    if (verdict.kind === 'block') {
      return { deny: `Blast Radius blocked this command: it breaks a house rule in ${RULES_FILE} (${rule}). Do not retry it or work around it; ask the user if it is needed.` }
    }
    const refused = await ask($, { command, rule, signal: next.signal })

    return refused ?? next(e)
  }).catch(($, e, next) => next(e))
}

files.hooks/lang.ts:
// MODZ kit — the interface language: English, or Turkish when the person sets MODZ_LANG=tr (the "env" of
// ~/.claude/settings.json). One value per mod: its register file reads the variable at session.start with
// `setLang(await $.env.get('MODZ_LANG'))` (the engine only admits an env read whose name is a literal), and every
// drawing reads it back through `pick` and `upper`.
export type Lang = 'en' | 'tr'

let current: Lang = 'en'

export const langOf = (value: unknown): Lang => (typeof value === 'string' && /^tr/i.test(value.trim()) ? 'tr' : 'en')

export function setLang(value: unknown): Lang {
  current = langOf(value)

  return current
}

export const lang = (): Lang => current

// The current language's entry of a table that fills in both: `pick({ en: 'Open', tr: 'Aç' })`.
export const pick = <T>(table: Readonly<Record<Lang, T>>): T => table[current]

// Capitals for eyebrows and labels: Turkish keeps its dotted İ, English never gets one.
export const upper = (text: string): string => text.toLocaleUpperCase(current)

files.hooks/measure.ts:
// Measures a risky command's blast radius. Never throws: a failed read is said, not hidden.

import { measureClean, measureRm } from './measure-files'
import { measureChanges, measureMigrations, measurePush } from './measure-git'
import { emptyReport } from './report'
import type { Report, Run } from './report'
import type { Risk } from './classify'
import { words } from './words'

const ERROR_CHARS = 160

export async function measure(run: Run, risk: Risk, cwd: string): Promise<Report> {
  try {
    if (risk.kind === 'rm') return await measureRm(run, risk, cwd)
    if (risk.kind === 'git-clean') return await measureClean(run, risk, cwd)
    if (risk.kind === 'migrate') return await measureMigrations(run, risk, cwd)
    if (risk.kind === 'git-push-force') return await measurePush(run, risk, cwd)

    return await measureChanges(run, risk, cwd)
  } catch (error) {
    const reason = String(error instanceof Error ? error.message : error).slice(0, ERROR_CHARS)

    return emptyReport('unknown', `${risk.label} (could not measure it)`, words().notes.unmeasured(reason))
  }
}

export const missingFolder = (risk: Risk): Report =>
  emptyReport('unknown', `${risk.label} in ${risk.dir}`, words().notes.missingFolder(String(risk.dir)))

files.hooks/report.ts:
// What a measurement found, as data: the drawing turns it into words, and
// `summary` is the sentence Claude reads when the command is refused.

export type FileRow = { name: string; bytes: number }

// Files grouped by the folder they sit in, biggest first; `files` is the head of the list.
export type Group = { dir: string; count: number; bytes: number; files: FileRow[] }

// One line of any other report: a changed file, a commit, a migration.
export type Item = { name: string; tag: string; meta: string; weight: number }

export type ReportKind = 'files' | 'changes' | 'commits' | 'migrations' | 'unknown'

export type Report = {
  kind: ReportKind
  summary: string
  count: number
  bytes: number | null
  groups: Group[]
  items: Item[]
  // How many of `count` are not in `items` (for `files`, not in any group's `files`).
  more: number
  // `files`: how many of them git tracks, so they could be restored.
  tracked: number | null
  // `commits`: the remote branch; `changes`: lines added and removed.
  where: string | null
  added: number
  removed: number
  // A line for the person, in their language, when something could not be measured.
  note: string | null
  // Measured, and the command would change nothing: it runs without a card.
  isEmpty: boolean
}

export type RunResult = { exitCode: number; stdout: string; stderr: string }

// `$.process.run`, handed in by the hooks module: measuring never touches `$` itself.
export type Run = (argv: string[], options: { cwd?: string; timeoutMs?: number }) => Promise<RunResult>

export const LIST_MAX = 10

const KIB = 1024
const DECIMAL_LIMIT = 10
const UNITS = ['KB', 'MB', 'GB', 'TB']

/** `286 KB`, `6.3 KB`; `mark` is the language's decimal mark. */
export function formatSize(bytes: number, mark: string): string {
  if (!Number.isFinite(bytes) || bytes < KIB) return `${bytes || 0} B`
  let n = bytes
  let i = -1
  while (n >= KIB && i < UNITS.length - 1) {
    n /= KIB
    i += 1
  }

  return `${n.toFixed(n < DECIMAL_LIMIT ? 1 : 0).replace('.', mark)} ${UNITS[i]}`
}

export function emptyReport(kind: ReportKind, summary: string, note: string | null): Report {
  return { kind, summary, count: 0, bytes: null, groups: [], items: [], more: 0, tracked: null, where: null, added: 0, removed: 0, note, isEmpty: false }
}

/** A measurement that found nothing the command could lose. */
export const nothingReport = (kind: ReportKind, summary: string): Report => ({ ...emptyReport(kind, summary, null), isEmpty: true })

export const plural = (count: number, one: string, many: string): string => `${count} ${count === 1 ? one : many}`

export const lines = (text: string): string[] => text.split('\n').filter(line => line !== '')

