// Every word the person reads on the card, in English or in Turkish (MODZ_LANG=tr).
// Read through `words()` at draw time: the language is set at session.start.

import { pick } from './lang'
import type { Report } from './report'
import type { Banner, Choice, View } from './view'
import { EN } from './words-en'
import { TR } from './words-tr'

export type Words = {
  eyebrow: string
  // The band has no title, so it says who is holding the command.
  holder: string
  showLess: string
  showMore: string
  cancel: { label: string; hotkey: string }
  doing: (isDelete: boolean) => string
  fullCommand: (command: string) => string
  // Said once the person kept their work.
  kept: string
  // The deny reason when Cancel was pressed, read by Claude and shown in the transcript.
  cancelWhy: string
  context: (place: { where: string | null; folder: string }) => string
  size: (bytes: number) => string
  folderCount: (count: number) => string
  moreFiles: (hidden: number, bytes: number) => string
  moreItems: (hidden: number, kind: Report['kind']) => string
  moreRows: (hidden: number) => string
  headline: (report: Report) => { payload: string; tail: string }
  banner: (report: Report) => Banner | null
  action: (report: Report) => View['action']
  notes: Notes
  edit: EditWords
  house: HouseWords
}

// The caution card for a command one of the person's house rules asks about.
export type HouseWords = {
  // "House rule: <the rule>", the card's banner.
  banner: (rule: string) => string
  // Said in place of a rule when the judge could not name which one.
  anyRule: string
  action: Choice
}

// The caution card for a file another chat edited within the last half hour.
export type EditWords = {
  eyebrow: string
  headline: (name: string, minutes: number) => string
  // The other chat's project folder, or '' when it is not known.
  context: (project: string) => string
  banner: string
  action: Choice
  cancel: Choice
  // Said once the person skipped the edit.
  skipped: string
  // The deny reason when Skip was pressed, read by Claude.
  cancelWhy: string
}

// Lines for the person when something could not be measured.
export type Notes = {
  noPaths: string
  decidedAtRun: (names: string) => string
  cleanFailed: (error: string) => string
  statusFailed: (error: string) => string
  refMissing: (ref: string) => string
  noDroppedCommits: (ref: string) => string
  cannotListMigrations: string
  migrationsFailed: (argv: string) => string
  unmeasured: (reason: string) => string
  missingFolder: (dir: string) => string
}

export const words = (): Words => pick({ en: EN, tr: TR })

files.hooks/kit/moving.ts:
// MODZ kit — a pane's drawings on the desktop, in motion (motion.ts). Any finished Svg source goes in under a key
// naming its place in the pane; out comes the props for an interactive Svg whose source stays byte-identical while
// what it shows does (stable.ts), so the desktop keeps its frame and its loops run on. The first draw of a key since
// the pane opened cascades in with the other new ones, a changed one sweeps once, a row's drawing answers hover, and
// every source says its colour scheme, else the frame is painted on an opaque white sheet.
import { entering, motionCss, SWEEP, WASH } from './motion'
import type { Cue } from './motion'
import { stableDrawings } from './stable'

export type Pic = { source: string; width?: number; height?: number; alt: string }

export type MovingPic<T extends Pic> = T & { isInteractive: true }

// `isRow`: the drawing is one row of a list, so hover washes it. `shows`: what it shows leaving out time that ticks
// ("2 dk önce"); a new source with the same `shows` is redrawn without the sweep, as is one drawn at a new width
// (the pane was resized: every drawing reflows, none of them changed).
export type MoveOpts = { isRow?: boolean; shows?: unknown }

export type PaneMotion = {
  // The pane opened again: each drawing enters anew.
  reset: () => void
  // `pic` as an interactive Svg's props, its source moving per the drawing's life under `key`, which names one
  // place in the pane (two drawings under one key would flip between their sources on every draw).
  pic: <T extends Pic>(key: string, pic: T, opts?: MoveOpts) => MovingPic<T>
}

// The width an svg's own tag gives it, for a drawing passed without one.
const TAG_WIDTH = /^[\s\S]*?<svg\b[^>]*?\swidth="([\d.]+)"/
const SVG = /^([\s\S]*?<svg\b[^>]*>)([\s\S]*)(<\/svg>\s*)$/
const SCHEME = '<style>:root{color-scheme:light dark}</style>'
// A scheme the drawing already says (not the `prefers-color-scheme` media query).
const SAYS_SCHEME = /(^|[^-\w])color-scheme\s*:/
// Draws within this long of each other are one pass of the pane; a new pass starts its cascade over.
const PASS_MS = 120
// The cascade stops lengthening here, so a long list is in place soon.
const MAX_ORDER = 12

// `source` with its scheme said and, per its cue, its entrance or its sweep; the hover wash for a row.
export function animate(source: string, spec: { cue: Cue; isRow?: boolean }): string {
  const parts = SVG.exec(source)
  if (parts === null) return source
  const [, open, inner, close] = parts
  const scheme = SAYS_SCHEME.test(inner) ? '' : SCHEME
  const lit = `${spec.isRow === true ? WASH : ''}${inner}${spec.cue.phase === 'change' ? SWEEP : ''}`
  const body = entering(lit, spec.cue)
  const css = motionCss(body)

  return `${open}${scheme}${css === '' ? '' : `<style>${css}</style>`}${body}${close}`
}

export function paneMotion(): PaneMotion {
  const drawings = stableDrawings<string>()
  const shown = new Map<string, { shows: string; width: string }>()
  const pass = { at: Number.NEGATIVE_INFINITY, entered: 0 }
  const begin = () => {
    const now = Date.now()
    if (now - pass.at > PASS_MS) pass.entered = 0
    pass.at = now
  }

  return {
    reset: () => {
      drawings.reset()
      shown.clear()
    },
    pic: (key, pic, opts = {}) => {
      begin()
      const what = `${opts.isRow === true ? 'row:' : ''}${pic.source}`
      const now = { shows: opts.shows === undefined ? what : JSON.stringify(opts.shows), width: String(pic.width ?? TAG_WIDTH.exec(pic.source)?.[1]) }
      const source = drawings.draw(key, what, built => {
        const order = built === 'enter' ? Math.min(MAX_ORDER, pass.entered++) : 0
        const before = shown.get(key)
        const isQuiet = before !== undefined && (before.shows === now.shows || before.width !== now.width)
        const phase = built === 'change' && isQuiet ? 'still' : built
        shown.set(key, now)

        return animate(pic.source, { cue: { phase, order }, isRow: opts.isRow })
      })

      return { ...pic, source, isInteractive: true }
    },
  }
}

files.hooks/svg-card.ts:
// The card's vector parts on desktop: header (tile + headline), risk banner, and the
// list with size bars on one global scale. After Delete, file rows get a drawn strike.

import { svgStyle } from './theme'
import { escape, fit, fitMiddle, icon, measure, svgOpen, tile } from './svg-kit'
import type { Banner, Row, View } from './view'
import { upper } from './lang'

const TILE = 38
const HEAD_X = 52
const HEAD_SIZE = 15.5
const CMD_SIZE = 14.5
const META_SIZE = 13
const ROW_H = 28
const GROUP_GAP = 8
const LIST_TOP = 14
const BAR_W = 96
const BAR_W_NARROW = 60
const NARROW = 420
const BAR_H = 6
const COUNT_W = 74
const SIZE_W = 64
const STRIKE_MS = 220
const STRIKE_STAGGER_MS = 60

const LINE_STEP = 19
const EYEBROW_BASELINE = 13
const EYEBROW_SIZE = 10.5
const EYEBROW_TRACKING = 1.05
const EYEBROW_DOT = 3
const EYEBROW_TEXT_X = 10
const META_GAP = 12
const FIRST_BASELINE = 35
const FULL_STEP = 18
const HEAD_BOTTOM = 6
const HEAD_MIN = 46
const GLUE = ' · '
// `measure` reads regular weight; a bold headline runs about this much wider.
const BOLD_GAIN = 1.06

type Line = { y: number; markup: string }

const commandRun = (command: string): string =>
  `<tspan class="mono" font-size="${CMD_SIZE}" font-weight="700" style="fill:var(--hi)">${escape(command)}</tspan>`

function payloadRun(view: View, room: number): string {
  const color = view.isPayloadEmpty ? 'var(--lo)' : 'var(--danger)'
  const tail = fit(view.tail, Math.max(0, room - measure(view.payload, { size: HEAD_SIZE, isBold: true })), { size: HEAD_SIZE })

  return `<tspan font-size="${HEAD_SIZE}" font-weight="700" style="fill:${color}">${escape(view.payload)}</tspan><tspan font-size="${HEAD_SIZE}" style="fill:var(--mid)">${escape(tail)}</tspan>`
}

// The headline on one line when it fits; in a narrow pane the command takes a line of its own
// and what it does goes under it, so neither is cut.
function headlineLines(view: View, room: number): Line[] {
  if (view.headline !== null) {
    return wrapTwo(view.headline, room / BOLD_GAIN, HEAD_SIZE).map((text, i) => ({
      y: FIRST_BASELINE + i * LINE_STEP,
      markup: `<tspan font-size="${HEAD_SIZE}" font-weight="700" style="fill:var(--hi)">${escape(text)}</tspan>`,
    }))
  }
  const spec = { size: CMD_SIZE, isMono: true, isBold: true }
  const said = measure(view.payload, { size: HEAD_SIZE, isBold: true }) + measure(view.tail, { size: HEAD_SIZE })
  const glue = `<tspan font-size="${HEAD_SIZE}" style="fill:var(--lo)">${GLUE}</tspan>`
  // English says what it does in the banner, so the headline is the command alone.
  if (view.payload === '' && view.tail === '') return [{ y: FIRST_BASELINE, markup: commandRun(fitMiddle(view.command, room, spec)) }]
  if (measure(view.command, spec) + measure(GLUE, { size: HEAD_SIZE }) + said <= room) {
    return [{ y: FIRST_BASELINE, markup: commandRun(view.command) + glue + payloadRun(view, room) }]
  }

  return [
    { y: FIRST_BASELINE, markup: commandRun(fitMiddle(view.command, room, spec)) },
    { y: FIRST_BASELINE + LINE_STEP, markup: payloadRun(view, room) },
  ]
}

/** `● HELD · BLAST RADIUS` in the card's role colour (DESIGN.md §3: every card opens with one), and the meta on the right while it fits. */
function eyebrowLine(view: View, room: number): string {
  const label = upper(view.eyebrow)
  const paint = `var(--${view.tone})`
  const labelW = measure(label, { size: EYEBROW_SIZE, isBold: true }) + [...label].length * EYEBROW_TRACKING
  const metaRoom = room - EYEBROW_TEXT_X - labelW - META_GAP
  const meta = view.context === '' || metaRoom < HEAD_X ? '' : fit(view.context, metaRoom, { size: META_SIZE })
  const y = EYEBROW_BASELINE

  return [
    `<circle cx="${HEAD_X + EYEBROW_DOT}" cy="${y - 3.5}" r="${EYEBROW_DOT}" style="fill:${paint}"/>`,
    `<text x="${HEAD_X + EYEBROW_TEXT_X}" y="${y}" font-size="${EYEBROW_SIZE}" font-weight="700" letter-spacing="${EYEBROW_TRACKING}" style="fill:${paint}">${escape(label)}</text>`,
    meta === '' ? '' : `<text x="${HEAD_X + room}" y="${y}" text-anchor="end" font-size="${META_SIZE - 1}" style="fill:var(--lo)">${escape(meta)}</text>`,
  ].join('')
}

export function headerSvg(view: View, width: number): { source: string; height: number } {
  const room = width - HEAD_X
  const lines = headlineLines(view, room)
  const fullY = (lines[lines.length - 1]?.y ?? FIRST_BASELINE) + FULL_STEP
  const full = view.fullCommand === null ? '' : `<text x="${HEAD_X}" y="${fullY}" class="mono" font-size="11.5" style="fill:var(--lo)">${escape(fitMiddle(view.fullCommand, room, { size: 11.5, isMono: true }))}</text>`
  const lastY = view.fullCommand === null ? (lines[lines.length - 1]?.y ?? FIRST_BASELINE) : fullY
  const height = Math.max(HEAD_MIN, lastY + HEAD_BOTTOM)

  return {
    height,
    source: [
      svgOpen(width, height),
      svgStyle(),
      tile(view.icon, { x: 0, y: 2, size: TILE, role: view.tone }),
      eyebrowLine(view, room),
      ...lines.map(line => `<text x="${HEAD_X}" y="${line.y}">${line.markup}</text>`),
      full,
      '</svg>',
    ].join(''),
  }
}

/** Words laid into at most two lines of `width` px. */
function wrapTwo(text: string, width: number, size: number): string[] {
  const words = text.split(' ')
  const first: string[] = []
  while (words.length > 0 && measure([...first, words[0]].join(' '), { size }) <= width) first.push(words.shift() ?? '')
  if (words.length === 0) return [first.join(' ')]

  return [first.join(' '), fit(words.join(' '), width, { size })].filter(line => line !== '')
}

export function bannerSvg(banner: Banner, width: number): { source: string; height: number } {
  const size = 13.5
  const textX = 40
  const wrapped = wrapTwo(banner.text, width - textX - 14, size)
  const height = wrapped.length === 1 ? 40 : 58
  const tone = banner.tone
  const texts = wrapped.map((line, i) => `<text x="${textX}" y="${25 + i * 18}" font-size="${size}" style="fill:var(--${tone})">${escape(line)}</text>`)

  return {
    height,
    source: [
      svgOpen(width, height),
      svgStyle(),
      `<rect x=".5" y=".5" width="${width - 1}" height="${height - 1}" rx="10" style="fill:var(--${tone}-tint);stroke:var(--${tone}-line)"/>`,
      icon('shield', { x: 14, y: 12, size: 16, color: `var(--${tone})` }),
      ...texts,
      '</svg>',
    ].join(''),
  }
}

type Columns = { barX: number; barW: number; sizeRight: number; countRight: number; hasCount: boolean }

const FOLDER_X = 26
const NAME_GAP = 8
const NAME_SIZE = 13
const FILE_X = 48
const MORE_X = 2
const NAME_X: Record<Row['kind'], number> = { file: FILE_X, more: MORE_X, folder: FOLDER_X, item: FOLDER_X }
const NAME_COLOR: Record<Row['kind'], string> = { folder: 'var(--hi)', more: 'var(--lo)', file: 'var(--mid)', item: 'var(--mid)' }
const BAR_GAP = 14

// A narrow pane gives up the folder's file count before it would cut a folder's name.
function columnsOf(width: number, rows: Row[]): Columns {
  const barW = width < NARROW ? BAR_W_NARROW : BAR_W
  const barX = width - barW
  const countRight = barX - BAR_GAP - SIZE_W
  const nameRoom = countRight - COUNT_W - FOLDER_X - NAME_GAP
  const hasCount = rows.every(row => row.kind !== 'folder' || measure(row.name, { size: NAME_SIZE, isBold: true }) <= nameRoom)

  return { barX, barW, sizeRight: barX - BAR_GAP, countRight, hasCount }
}

function bar(row: Row, top: number, cols: Columns): string {
  if (row.share === null) return ''
  const y = top + (ROW_H - BAR_H) / 2
  const fill = Math.max(row.share > 0 ? BAR_H : 0, Math.round(cols.barW * Math.min(1, row.share)))
  const color = row.kind === 'folder' ? 'var(--mid)' : 'var(--lo)'

  return `<rect x="${cols.barX}" y="${y}" width="${cols.barW}" height="${BAR_H}" rx="3" style="fill:var(--track)"/><rect x="${cols.barX}" y="${y}" width="${fill}" height="${BAR_H}" rx="3" style="fill:${color}"/>`
}

type Placed = { row: Row; top: number; strikeIndex: number | null }

// A git status letter by role: added Moss, modified Amber, deleted Flare, renamed Tide; a commit hash stays meta.
const STATUS_ROLE: Record<string, string> = { A: 'ok', M: 'warn', D: 'danger', R: 'read', C: 'read', U: 'danger' }
const DIFF = /^\+(\d+) −(\d+)$/

export const tagPaint = (tag: string): string => {
  const role = STATUS_ROLE[tag.trim().charAt(0)]

  return tag.length <= 2 && role !== undefined ? `var(--${role})` : 'var(--lo)'
}

/** `+61 −0`: the added count in Moss, the removed one in Flare; any other size stays as one run. */
function sizeRuns(size: string, paint: string): string {
  const diff = DIFF.exec(size)
  if (diff === null) return `<tspan style="fill:${paint}">${escape(size)}</tspan>`

  const paintOf = (count: string, role: string) => (count === '0' ? 'var(--lo)' : `var(--${role})`)

  return `<tspan style="fill:${paintOf(diff[1] ?? '', 'ok')}">+${diff[1]}</tspan><tspan style="fill:${paintOf(diff[2] ?? '', 'danger')}"> −${diff[2]}</tspan>`
}

function nameRight(row: Row, cols: Columns): number {
  if (row.kind === 'folder' && cols.hasCount) return cols.countRight - COUNT_W
  if (row.size === '') return cols.barX - BAR_GAP

  return cols.sizeRight - SIZE_W
}

function rowSvg(placed: Placed, cols: Columns): string {
  const { row, top } = placed
  const base = top + 18
  const isFolder = row.kind === 'folder'
  const nameX = NAME_X[row.kind]
  const tagW = row.tag === '' ? 0 : measure(row.tag, { size: 11.5, isMono: true }) + 10
  const right = nameRight(row, cols)
  const spec = { size: NAME_SIZE, isBold: isFolder }
  const name = fitMiddle(row.name, Math.max(40, right - nameX - tagW - NAME_GAP), spec)
  const glyph = row.kind === 'more' ? '' : icon(row.icon, { x: isFolder || row.kind === 'item' ? 2 : 26, y: top + 7, size: isFolder ? 16 : 14, color: isFolder ? 'var(--mid)' : 'var(--lo)' })
  const tag = row.tag === '' ? '' : `<text x="${nameX}" y="${base}" class="mono" font-size="11.5" font-weight="${tagPaint(row.tag) === 'var(--lo)' ? 400 : 700}" style="fill:${tagPaint(row.tag)}">${escape(row.tag)}</text>`
  const nameColor = NAME_COLOR[row.kind]
  const dim = placed.strikeIndex === null ? '' : ` class="dim" style="animation-delay:${placed.strikeIndex * STRIKE_STAGGER_MS}ms"`
  const texts = [
    `<text x="${nameX + tagW}" y="${base}" font-size="13" font-weight="${isFolder ? 600 : 400}" style="fill:${nameColor}">${escape(name)}</text>`,
    row.count === '' || !cols.hasCount ? '' : `<text x="${cols.countRight}" y="${base}" text-anchor="end" font-size="12.5" style="fill:var(--lo)">${escape(row.count)}</text>`,
    row.size === '' ? '' : `<text x="${cols.sizeRight}" y="${base}" text-anchor="end" class="num" font-size="12.5" font-weight="${isFolder ? 600 : 400}">${sizeRuns(row.size, isFolder ? 'var(--hi)' : 'var(--lo)')}</text>`,
  ]

  return `${glyph}<g${dim}>${tag}${texts.join('')}</g>${bar(row, top, cols)}${strike(placed, nameX + tagW, measure(name, spec))}`
}

function strike(placed: Placed, x: number, textWidth: number): string {
  if (placed.strikeIndex === null) return ''
  const y = placed.top + 13.5
  const delay = placed.strikeIndex * STRIKE_STAGGER_MS

  return `<path d="M${x - 4} ${y}H${x + textWidth + 4}" pathLength="1" class="st" style="stroke:var(--danger);animation-delay:${delay}ms"/>`
}

// The struck state is the resting style, so reduced motion (no animation) still shows it; the animation plays into it.
const STRIKE_CSS = `.st{fill:none;stroke-width:1.5;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:0;animation:draw ${STRIKE_MS}ms cubic-bezier(.2,.8,.2,1) backwards}.dim{opacity:.45;animation:dim ${STRIKE_MS}ms ease-out backwards}@keyframes draw{from{stroke-dashoffset:1}}@keyframes dim{from{opacity:1}}`

/** The list as one drawing; `isStruck` strikes every file, item and the overflow line. */
export function listSvg(rows: Row[], width: number, isStruck: boolean): { source: string; height: number } {
  const cols = columnsOf(width, rows)
  const placed: Placed[] = []
  let y = LIST_TOP
  let struck = 0
  rows.forEach((row, index) => {
    if (row.kind === 'folder' && index > 0) y += GROUP_GAP
    const isStrikable = isStruck && row.kind !== 'folder'
    placed.push({ row, top: y, strikeIndex: isStrikable ? struck++ : null })
    y += ROW_H
  })
  const height = y + 4

  return {
    height,
    source: [
      svgOpen(width, height),
      svgStyle(isStruck ? STRIKE_CSS : ''),
      `<path d="M0 .5H${width}" style="stroke:var(--line)"/>`,
      ...placed.map(item => rowSvg(item, cols)),
      '</svg>',
    ].join(''),
  }
}

